const { chromium } = require('/tmp/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const outDir = '/Users/sinchunyeung/github/simplification-of-trajectory-streams/web/usability';
  async function shoot(width, height, name) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5051/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    // Select preloaded trace without leaving the picker open
    await page.evaluate(() => {
      const sel = document.getElementById('traceSelect');
      if (sel) {
        sel.value = '1';
        sel.dispatchEvent(new Event('change', { bubbles: true }));
      }
      const picker = document.getElementById('tracePicker');
      if (picker) {
        picker.classList.remove('open');
        picker.setAttribute('aria-hidden', 'true');
      }
      const label = document.getElementById('preloadedLabel');
      if (label && sel && sel.selectedOptions[0]) label.textContent = sel.selectedOptions[0].textContent;
    });
    await page.click('#loadBtn', { force: true });
    await page.waitForFunction(() => document.body.classList.contains('playback-ready') || (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'), { timeout: 180000 });
    await page.waitForTimeout(600);
    await page.evaluate(() => {
      document.body.classList.remove('mobile-panel-closed');
      const layers = document.getElementById('layersSection');
      if (layers) layers.classList.add('layers-open');
      const acc = document.getElementById('accordionBaseline');
      if (acc) acc.open = true;
      const hint = document.getElementById('baselineLayerHint');
      if (hint) hint.scrollIntoView({ block: 'center' });
    });
    await page.waitForTimeout(250);
    const info = await page.evaluate(() => {
      const fc = document.querySelector('.file-controls');
      const cs = fc ? getComputedStyle(fc) : null;
      return {
        hint: document.getElementById('baselineLayerHint')?.textContent?.trim() || '',
        fileControlsDisplay: cs?.display || null,
        fileControlsWidth: fc ? fc.getBoundingClientRect().width : null,
        scrollWidth: document.documentElement.scrollWidth,
        headerRunHidden: !!document.getElementById('headerBaselineRunBtn')?.hidden,
      };
    });
    console.log(name, JSON.stringify({ ...info, innerWidth: width }));
    await page.screenshot({ path: `${outDir}/${name}`, fullPage: false });
    await page.close();
  }
  await shoot(390, 844, 'layers-compare-hint-mobile-390-live.png');
  await shoot(1280, 800, 'layers-compare-hint-mobile-1280-live.png');
  await browser.close();
  console.log('done');
})().catch(e => { console.error(e); process.exit(1); });
